def draw_grid(screen, grid, cell=32):
    for y, row in enumerate(grid):
        for x, val in enumerate(row):
            color = (40, 200, 90) if val else (0, 0, 0)
            pygame.draw.rect(screen, color, (x * cell, y * cell, cell - 1, cell - 1))
    pygame.display.flip()

